public class Solution {
    public static String dashed(int[] arr) {
        // CONTRACT: elements joined by "-", e.g. {1,2,3} -> "1-2-3";
        // empty array -> "".
        String out = "";
        for (int i = 0; i < arr.length; i++) {
            out += "-";
        }
        return out;
    }
}

